import{a as e,i as t,r as n,t as r}from"./app-Cwfdj7tv.js";var i=JSON.parse(`{"path":"/guide/economy.html","title":"经济流转","lang":"zh-CN","frontmatter":{},"git":{"updatedTime":1790447772000,"contributors":[{"name":"ShiroMizu","username":"","email":"ShiroMizuTan@163.com","commits":1}],"changelog":[{"hash":"cb44449b03168146c3922cb91a45aa1f8a210a5e","time":1790447772000,"email":"ShiroMizuTan@163.com","author":"ShiroMizu","message":"docs: add economy and guess game pages, update shop with buff and scratch card"}]},"filePathRelative":"guide/economy.md"}`),a={name:`economy.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="经济流转" tabindex="-1"><a class="header-anchor" href="#经济流转"><span>经济流转</span></a></h1><p>金币可以在用户之间流动，也可以把背包里的物品送给别人。</p><div class="hint-container warning"><p class="hint-container-title">注意</p><p>以下指令中的目标用户<strong>必须使用实际 @</strong>。@ 不会出现在文本里，但参数解析不受影响。</p></div><h2 id="转账" tabindex="-1"><a class="header-anchor" href="#转账"><span>转账</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>转账</code> / <code>转金币</code> / <code>给钱</code></td><td>实际 @ 用户 + 金额</td><td><code>.转账 @小明 100</code></td><td>把自己的金币转给对方</td></tr></tbody></table><h2 id="赠送物品" tabindex="-1"><a class="header-anchor" href="#赠送物品"><span>赠送物品</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>赠送</code> / <code>送给</code> / <code>送礼</code></td><td>实际 @ 用户 + 物品名 [+ 数量]</td><td><code>.赠送 @小明 好感药水 3</code></td><td>把自己的物品送给对方</td></tr></tbody></table><h2 id="金币榜" tabindex="-1"><a class="header-anchor" href="#金币榜"><span>金币榜</span></a></h2><table><thead><tr><th>指令</th><th>参数</th><th>示例</th><th>说明</th></tr></thead><tbody><tr><td><code>金币榜</code> / <code>金币排行</code> / <code>金币排行榜</code> / <code>富豪榜</code></td><td>无</td><td><code>.金币榜</code></td><td>展示金币最多的前 5 名</td></tr></tbody></table><p>榜单按金币降序取前 5 名，<strong>金币为 0 的用户不参与排名</strong>；金币相同时先注册的靠前，名次稳定。 榜单只读，查看榜单<strong>不会给自己建号</strong>。</p><h2 id="约定与限制" tabindex="-1"><a class="header-anchor" href="#约定与限制"><span>约定与限制</span></a></h2><ul><li>金额与数量必须为正；单次转账金额上限 <strong>100000 金币</strong></li><li>不能转账 / 赠送给自己</li><li>发送方余额或持有量不足会被拒绝</li><li>接收方背包中该物品已达堆叠上限时会拒绝赠送，<strong>不会静默丢弃</strong></li><li>转账与赠送都只在<strong>一次数据库事务</strong>内完成，不会出现「扣了钱对方没收到」</li><li>钱包 / 背包的增减与物品流转都不改变任何一方的平台绑定关系</li></ul><div class="hint-container tip"><p class="hint-container-title">提示</p><p>所有涉及金币的操作（签到 / 购买 / 转账 / 刮刮乐 / 猜大小）对同一用户是<strong>串行执行</strong>的， 并发下不会算错账。</p></div>`,13)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};